import {classifySpellMisfire,applyMisfireCombatTrauma,applyMisfireArcaneTrauma} from './hmk-spell-misfire-effects.js';
/** HMK 2024 pp.7, 22, 200–202, 227: verified Doom Flame area source.
 * Restricted supported case: primary Peleahn, normal audible cant and gesture,
 * no Focus/Joined/attenuation/other spell modifiers, clear undisturbed conditions.
 * The source, targets, effects and initiative turn are committed together.
 * No die is ever generated by the program.
 */
import {successLevel,SL} from '../rules/tests.js';
import {combatFatigueTotals,validateCombatState,dueInjuryMorale} from './persistent-combat-state.js';
import {validateEncounterSequence,currentEncounterActor,recordScheduledHitCommit,finishEncounterTurn} from './encounter-turn-sequence.js';
import {prepareSourceBoundAreaCohort,finalizeSourceBoundAreaCohort} from './hmk-area-atomic-cohort.js';
import {persistVerifiedCombatSnapshot} from './verified-combat-storage.js';
import {previewProactiveDoomFlameEvade} from './hmk-proactive-area-evade.js';
const cp=structuredClone,js=JSON.stringify;
const check=(v,m)=>{if(!v)throw Error(m)};
const int=(v,a,b)=>Number.isSafeInteger(v)&&v>=a&&v<=b;
const fireSunsign=Object.freeze({'Ùlándus':-5,'Arálius':0,'Fenéri':5,'Áhnù':10,'Angberélius':15,'Nadái':10,'Hîrin':5,'Táræl':0,'Tai':-5,'Skôrus':-10,'Masâra':-15,'Ládo':-10});
const distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
function casterFacts(c){
 check(c?.id&&c.hmk?.arcane?.primaryConvocation==='Pèleáhn'&&
  Array.isArray(c.hmk.arcane.knownSpells)&&c.hmk.arcane.knownSpells.includes('Doom Flame'),
  'Chybí doložená Primary Pèleáhn a naučené kouzlo Doom Flame na kartě postavy');
 check(!(c.hmk.arcane.auralShockLevels>0)&&!c.hmk.arcane.activeMisfireWarp&&
  !c.hmk.arcane.pendingPsycheTraitChoice,
  'HMK p190/203: Aural Shock a nevyřešené Aura warpage blokují neověřené další sesílání');
 const p=c.hmk.skills?.filter(x=>String(x.name).toLowerCase()==='pvarism');
 check(p?.length===1&&int(p[0].ml,0,200),'Chybí aktuální Pvarism ML');
 const sun=c.hmk.identity?.sunsign;
 check(Object.hasOwn(fireSunsign,sun),'Chybí jednoznačné ověřené Sunsign kouzelníka');
 const spellML=p[0].ml+fireSunsign[sun]-12; // Primary CD0, Doom Flame CL VI.
 check(spellML>=10&&spellML<=200,'Spell ML musí umožnit kladný Spell Index');
 return {pvarismML:p[0].ml,sunsign:sun,sunsignModifier:fireSunsign[sun],spellML,si:Math.floor(spellML/10)};
}
/** Source declaration and geometry are fixed before the GM supplies dice.
 * Casting must have started as a two-round concentrated Incant, and that
 * commitment must have been completed BEFORE this actor's spellfire turn. */
export function prepareDoomFlameSource({id,sequence,document,casterId,center,seedFire,
 conditionsConfirmed=false,gmConfirmed=false}={}){
 check(gmConfirmed&&conditionsConfirmed,'GM musí potvrdit viditelnost, klid a běžný cant i gesture');
 const seq=validateEncounterSequence(sequence),caster=document?.characters?.find(c=>c.id===casterId);
 check(caster&&currentEncounterActor(seq)===casterId&&seq.active&&!seq.pendingEndTurnAction&&!seq.interruptActiveId,
  'Spellfire musí být právě aktivním tahem kouzelníka');
 check(typeof id==='string'&&id.length>0&&id.length<=140&&
  !seq.log.some(x=>x.eventId===id),'Neplatné nebo duplicitní ID Area');
 const facts=casterFacts(caster),casterState=caster.hmk.combatState;
 validateCombatState(casterState);
 check(!['STN','INC','UNC','KIA'].includes(casterState.shock)&&
  !casterState.coma?.active&&
  !['withdrawing','routed','catatonic'].includes(casterState.morale?.state)&&
  !casterState.morale?.surrender?.active&&!casterState.posture?.passNextTurn&&
  !['STN','INC','UNC','KIA'].includes(seq.entryShock)&&
  !['withdrawing','routed','catatonic'].includes(seq.entryMorale),
  'Doom Flame: Shock, Morale či povinný Pass vylučují Spellfire');
 check(caster.hmk.arcane.verifiedGestureEncumbrance===0&&
  casterState.wounds.length===0&&!casterState.pendingManeuver&&
  !casterState.mishaps?.some(x=>!x.resolved),
  'Bez přesně ověřeného nulového ENC nebo při zranění není Casting EML bezpečně doložen; chybí příslušný modifikátor');
 const commitment=seq.commitments?.[casterId];
 check(commitment?.status==='completed'&&commitment.durationRounds===2&&
  commitment.completedRound===seq.round&&
  seq.log.some(x=>x.type==='concentration-complete'&&x.actorId===casterId&&x.round===seq.round&&x.durationRounds===2),
  'Doom Flame vyžaduje dvě doložená kola koncentrace a dokončený spellstart');
 const world=seq.spatialUnits;
 check(Array.isArray(world)&&world.length===seq.order.length&&
  seq.order.every(who=>world.filter(u=>u.id===who&&Number.isFinite(u.x)&&Number.isFinite(u.y)).length===1),
  'Chybí úplné souřadnice střetnutí pro určení všech cílů');
 check(!seq.spatialBarriers?.length,'LOS přes překážky vyžaduje další geometrické ověření; Area zablokována');
 for(const point of [center,seedFire])check(point&&Number.isFinite(point.x)&&Number.isFinite(point.y),
  'Chybí skutečné souřadnice místa výbuchu a zdrojového ohně');
 const origin=world.find(u=>u.id===casterId);
 check(distance(origin,seedFire)<=5+1e-7,'Doom Flame potřebuje skutečný seed flame nejvýše 5 ft od kouzelníka');
 check(distance(origin,center)<=facts.si*30+1e-7,'Cíl leží mimo doložený Doom Flame Range');
 const radius=facts.si*5/4; // printed DIAMETER = half SI × 5 ft.
 const targetIds=world.filter(u=>distance(u,center)<=radius+1e-7).map(u=>u.id);
 check(targetIds.length>0,'Koule nezasahuje žádnou evidovanou postavu');
 check(seq.order.every(who=>document.characters.filter(c=>c.id===who).length===1),
  'Area nemá všechny účastníky v jednom autoritativním dokumentu');
 const eml=Math.max(0,Math.min(100,facts.spellML-combatFatigueTotals(casterState).total));
 check(eml>0,'Aktuální Casting EML nedovoluje doložit úspěšný Spellfire');
 return {format:'hmk-doom-flame-stage-v1',id,timelineId:seq.timelineId,round:seq.round,
  casterId,center:cp(center),seedFire:cp(seedFire),radius,targetIds,spellML:facts.spellML,
  spellIndex:facts.si,spellEML:eml,castingRoll:null,fireD4:null,
  conditionsConfirmed:true,sequenceWitness:js(seq),documentWitness:js(document),phase:'casting-d100'};
}
export function doomFlameRequirement(stage){
 check(stage?.format==='hmk-doom-flame-stage-v1','Neplatný Area průvodce');
 if(stage.phase==='casting-d100')return {id:'castingRoll',faces:100,label:`Doom Flame Casting d100 (EML ${stage.spellEML})`};
 if(stage.phase==='impact-d4')return {id:'fireD4',faces:4,label:'Doom Flame Fire Impact d4'};
 if(stage.phase==='misfire-d100')return {id:'misfireD100',faces:100,label:'Spell Misfire d100 (HMK str. 203)'};
 if(stage.phase==='total-release-spirit')return {id:'totalReleaseSpiritD100',faces:100,label:`Total Release Spirit d100 (EML ${stage.totalReleaseSpiritEML}, HMK str.203)`};
 if(stage.phase==='total-release-spirit-loss')return {id:`spiritLossD6_${stage.totalReleaseSpiritLossDice.length+1}`,faces:6,label:`Total Release: skutečný Spirit ML loss d6 (${stage.totalReleaseSpiritLossDice.length+1}/${stage.totalReleaseSpiritLossCount})`};
 if(stage.phase==='total-release-hyperburst-pending')return {kind:'total-release-hyperburst-pending'};
 if(stage.phase==='misfire-form-failure')return {kind:'misfire-form-failure'};
 if(stage.phase==='misfire-mental-trauma')return {kind:'misfire-mental-trauma'};
 if(stage.phase==='misfire-unhandled')return {kind:'misfire-unhandled'};
 return {kind:stage.phase==='ready'?'complete':'failed'};
}
export function submitDoomFlameDie(stage,value){
 const req=doomFlameRequirement(stage);
 check(req.faces&&int(value,1,req.faces),'Chybí skutečný fyzický hod d'+req.faces);
 if(stage.phase==='casting-d100'){
  const sl=successLevel(value,stage.spellEML);
  // Misfire is NOT a failed/no-effect casting; it has mandatory consequences.
  // That branch is intentionally not writable without a complete Misfire guide.
  // HMK p202: F produces no effect, but CL VI still imposes base fatigue 5 + 10.
  // CF requires a separate physical Spell Misfire and is never treated as F.
  if(sl===SL.F)return {...stage,castingRoll:value,castingSL:'F',castingFatigue:15,phase:'failed'};
  if(sl===SL.CF)return {...stage,castingRoll:value,castingSL:'CF',castingFatigue:20,phase:'misfire-d100'};
  return {...stage,castingRoll:value,castingSL:sl===SL.CS?'CS':'S',phase:'impact-d4'};
 }
 if(stage.phase==='total-release-spirit'){
  const sl=successLevel(value,stage.totalReleaseSpiritEML);
  const name=sl===SL.CF?'CF':sl===SL.F?'F':sl===SL.CS?'CS':'S';
  const dice=sl===SL.CF?0:sl===SL.F?6:sl===SL.S?4:2;
  return {...stage,totalReleaseSpiritRoll:value,totalReleaseSpiritSL:name,
   totalReleaseSpiritMLLoss:dice?null:0,totalReleaseSpiritLossCount:dice,
   phase:dice?'total-release-spirit-loss':'total-release-hyperburst-pending'};
 }
 if(stage.phase==='total-release-spirit-loss'){
  const rolls=[...stage.totalReleaseSpiritLossDice,value];
  check(rolls.length<=stage.totalReleaseSpiritLossCount,'Přebytečný Spirit ML loss d6');
  return {...stage,totalReleaseSpiritLossDice:rolls,
   totalReleaseSpiritMLLoss:rolls.length===stage.totalReleaseSpiritLossCount?
    rolls.reduce((a,b)=>a+b,0):null,
   phase:rolls.length===stage.totalReleaseSpiritLossCount?'total-release-hyperburst-pending':'total-release-spirit-loss'};
 }
 if(stage.phase==='misfire-d100'){
  // HMK p.203: the first three Form Failure bands have a fully stated
  // mechanical consequence. Other misfires require different followups
  // (Aural Shock, Psyche or Raw Principle) and stay blocked here.
  const derived=classifySpellMisfire(value,6);
  const extra=derived.category==='form-failure'?derived.extraFatigue:null;
  if(extra===null){
   if(value===100){
    // HMK p.203: casting Misfire 100 is immediately followed by a
    // physical Spirit test with -5 per spell CL (VI => -30), including
    // applicable existing fatigue. Do not commit until the p.204 six-round
    // Pèleáhn Hyper Burst is supported by the encounter scheduler.
    const document=JSON.parse(stage.documentWitness);
    const caster=document.characters?.find(c=>c.id===stage.casterId);
    const spirit=caster?.hmk?.skills?.filter(x=>String(x.name).trim().toLowerCase()==='spirit');
    check(spirit?.length===1&&int(spirit[0].ml,0,200),
     'Total Release vyžaduje jednoznačnou aktuální Spirit ML kouzelníka');
    const fatigue=combatFatigueTotals(caster.hmk.combatState).total;
    const eml=Math.max(0,spirit[0].ml-30-fatigue);
    return {...stage,misfireD100:100,misfireKind:'total-release',crucialMisfire:true,
     misfirePsycheStress:3,totalCastingFatigue:20,totalReleaseSpiritML:spirit[0].ml,
     totalReleaseSpiritEML:eml,totalReleaseFatigueBefore:fatigue,
     totalReleaseSpiritRoll:null,totalReleaseSpiritSL:null,
     totalReleaseSpiritLossCount:null,totalReleaseSpiritLossDice:[],
     phase:'total-release-spirit'};
   }
   // HMK p203: immediate effects of distortion/confusion and principle leak.
   const {psycheStress:psyche,auralShock:aural,kind}=derived;
   return {...stage,misfireD100:value,misfireKind:kind,crucialMisfire:derived.crucial,
    misfirePsycheStress:psyche,misfireAuralShock:aural,misfireExtraFatigue:0,
    totalCastingFatigue:20,phase:'misfire-mental-trauma'};
  }
  const kind=derived.kind;
  const crucial=derived.crucial;
  return {...stage,misfireD100:value,misfireKind:kind,crucialMisfire:crucial,
   misfireExtraFatigue:extra,totalCastingFatigue:20+extra,phase:'misfire-form-failure'};
 }
 return {...stage,fireD4:value,strikeImpact:value+stage.spellIndex+(stage.castingSL==='CS'?4:0),
  castingFatigue:stage.castingSL==='CS'?10:15,phase:'ready'};
}
/** Construct full all-target result, including a source event which exists only
 * within the UNCOMMITTED transaction. Never persist source separately. */
export function resolveDoomFlameCohort({stage,document,rollsByTarget,noEvadeTargetIds,proactiveEvades=null,method='weighted'}={}){
 check(stage?.phase==='ready'&&js(document)===stage.documentWitness,'Area průvodce nebo živý dokument se změnily');
 const proactive=Object.entries(proactiveEvades??{});
 check(proactive.length<=1&&proactive.every(([id])=>stage.targetIds.includes(id)),
  'Proaktivní Evade musí jednoznačně patřit jednomu zasaženému cíli (více současných pohybů vyžaduje další kontrolu)');
 check(Array.isArray(noEvadeTargetIds)&&new Set(noEvadeTargetIds).size===noEvadeTargetIds.length&&
  noEvadeTargetIds.every(id=>stage.targetIds.includes(id))&&
  noEvadeTargetIds.every(id=>!proactiveEvades?.[id]),
  'Doložená proactive Evade nemůže být současně odmítnuta');
 const original=validateEncounterSequence(document.combatRuntime.sequence);
 check(js(original)===stage.sequenceWitness,'Změna Initiative během Area hodů');
 // A sessionStorage draft is NOT proof. Rebuild the source and both physical
 // casting steps from live characters, concentration, geometry and GM dice.
 const verifiedStart=prepareDoomFlameSource({id:stage.id,sequence:original,document,
  casterId:stage.casterId,center:stage.center,seedFire:stage.seedFire,
  conditionsConfirmed:true,gmConfirmed:true});
 const verifiedFinal=submitDoomFlameDie(submitDoomFlameDie(verifiedStart,stage.castingRoll),stage.fireD4);
 check(js(verifiedFinal)===js(stage),'Podvržený Spell EML, Area geometrie, Casting SL nebo Impact d4');
 const states=Object.fromEntries(document.characters.map(c=>[c.id,c.hmk?.combatState]));
 const sourceSeq=recordScheduledHitCommit(original,{actorId:stage.casterId,states,gmConfirmed:true});
 let proactiveProof=null;
 if(proactive.length){
  const [targetId,requested]=proactive[0];
  proactiveProof=previewProactiveDoomFlameEvade({stage,document,targetId,
   path:requested.path,battlefield:requested.battlefield,
   witnessedProjectile:requested.witnessedProjectile,gmConfirmed:true});
  const evidenceId=`${stage.id}:proactive-evade:${targetId}`;
  check(!sourceSeq.spatialEvents?.some(e=>e.id===evidenceId)&&
   !sourceSeq.log.some(e=>e.type==='proactive-area-evade'&&e.actorId===targetId&&e.dueRound>=original.round),
   'Evade už byla jednou uplatněna nebo stále dluží příští vlastní tah');
  sourceSeq.spatialUnits=sourceSeq.spatialUnits.map(u=>u.id===targetId?{...u,...proactiveProof.projection.finalPosition}:u);
  sourceSeq.spatialEvents??=[];
  sourceSeq.spatialEvents.push({id:evidenceId,actorId:targetId,round:stage.round,
   timelineId:stage.timelineId,projection:cp(proactiveProof.projection),proactiveAreaSourceId:stage.id});
  sourceSeq.log.push({type:'proactive-area-evade',eventId:evidenceId,sourceEventId:stage.id,
   round:stage.round,dueRound:proactiveProof.nextIRActionDue.round,actorId:targetId,
   spatialEventId:evidenceId,alreadyMoved:true});
 }
 const affectedIds=sourceSeq.spatialUnits.filter(u=>distance(u,stage.center)<=stage.radius+1e-7).map(u=>u.id);
 check(affectedIds.length>0,'Doom Flame bez jakéhokoli zasaženého cíle vyžaduje zvláštní nezraněnou Area transakci');
 check(affectedIds.every(id=>stage.targetIds.includes(id)),'Proaktivní Evade změnila množinu cílů neověřeným způsobem');
 check(affectedIds.every(id=>noEvadeTargetIds.includes(id)!==(rollsByTarget?.[id]?.dodgeD100!=null)),
  'HMK p166: každý stále zasažený cíl musí odmítnout Evade nebo dodat doložený fyzický Dodge d100');
 check(Object.keys(rollsByTarget??{}).length===affectedIds.length&&
  Object.keys(rollsByTarget).every(id=>affectedIds.includes(id)),
  'Hody Area musí odpovídat skutečným cílům až po Evade pohybu');
 const token=Object.keys(sourceSeq.confirmedHits).find(k=>!original.confirmedHits?.[k]);
 check(token,'Nepodařilo se doložit jedinečný origin Attack token');
 sourceSeq.confirmedHits[token].actionKind='area';sourceSeq.confirmedHits[token].sourceEventId=stage.id;
 const event={type:'area-source-resolved',eventId:stage.id,timelineId:stage.timelineId,
  round:stage.round,actorId:stage.casterId,producer:'hmk-guided-verified-area-source-v1',
  completed:true,result:'success',originHitToken:token,aspect:'fire',strikeImpact:stage.strikeImpact,
  targetIds:[...affectedIds],geometryVerified:true,targetsVerified:true,diceVerified:true,
  geometryWitness:js({center:stage.center,seedFire:stage.seedFire,radius:stage.radius,
   targetIds:affectedIds,units:sourceSeq.spatialUnits,proactiveEvade:proactiveProof?.projection??null}),spell:'Doom Flame',
  castingEML:stage.spellEML,spellIndex:stage.spellIndex,castingSL:stage.castingSL,
  proactiveEvadeDeclinedBy:cp(noEvadeTargetIds),
  physicalDice:[{faces:100,value:stage.castingRoll,source:'GM-entered-physical-die'},
   {faces:4,value:stage.fireD4,source:'GM-entered-physical-die'}]};
 sourceSeq.log.push(event);
 const args={sequence:sourceSeq,sourceEventId:stage.id,characters:document.characters,
  states,inventory:document.inventory,rollsByTarget,method};
 const cohortStage=prepareSourceBoundAreaCohort(args);
 const cohortPlan=finalizeSourceBoundAreaCohort({stage:cohortStage,...args});
 const afterStates={...states,...cohortPlan.states};
 // Casting fatigue applies after spellfire; no extra die is generated.
 const casterState=cp(afterStates[stage.casterId]);validateCombatState(casterState);
 casterState.fatigue.windedness+=stage.castingFatigue;
 casterState.events.push({id:stage.id+':casting-fatigue',round:stage.round,type:'hmk-casting-fatigue',
  details:{spell:'Doom Flame',fatigue:stage.castingFatigue,castingRoll:stage.castingRoll}});
 casterState.lastRound=Math.max(casterState.lastRound,stage.round);
 validateCombatState(casterState);afterStates[stage.casterId]=casterState;
 check(dueInjuryMorale(casterState).length===0,'Kouzelník má dosud splatnou Injury Morale');
 const finalSeq=finishEncounterTurn(cohortPlan.sequence,afterStates,{action:'incant',gmConfirmed:true});
 check(!finalSeq.pendingEndTurnAction,'Povinné následky na konci tahu musí být samostatně vyhodnoceny');
 return {format:'hmk-doom-flame-complete-v1',stageId:stage.id,sequence:finalSeq,
  states:Object.fromEntries([...new Set([...affectedIds,stage.casterId])].map(id=>[id,afterStates[id]])),
  results:cohortPlan.results,sourceEvent:event,targetIds:[...affectedIds],
  ...(proactiveProof?{proactiveEvadeProof:proactiveProof}: {})};
}
export function persistGuidedDoomFlame({stage,rollsByTarget,noEvadeTargetIds,proactiveEvades=null,plan,document,storage,key,baseline,method='weighted'}={}){
 check(plan?.format==='hmk-doom-flame-complete-v1'&&document&&js(document)===stage?.documentWitness,
  'Neúplný či zastaralý Area zápis');
 const fresh=resolveDoomFlameCohort({stage,document,rollsByTarget,noEvadeTargetIds,proactiveEvades,method});
 check(js(fresh)===js(plan),'Podvržený nebo změněný Area výsledek');
 const out=cp(document);
 for(const [id,state] of Object.entries(fresh.states)){
  const c=out.characters.find(c=>c.id===id);
  check(c?.hmk&&Array.isArray(c.hmk.injuries),'Chybí postava nebo trvalý seznam zranění');
  c.hmk.combatState=cp(state);
  // Keep all Area wounds, including compounded wounds, consistent in the
  // character sheet's independent injury record.
  for(const wound of state.wounds){
   const entry=c.hmk.injuries.find(w=>w.id===wound.id&&w.combatRecord===true);
   if(entry)Object.assign(entry,{severity:wound.severity,level:wound.level,location:wound.location});
   else if(!c.hmk.injuries.some(w=>w.id===wound.id))c.hmk.injuries.push({...cp(wound),combatRecord:true});
  }
 }
 out.combatRuntime.sequence=cp(fresh.sequence);
 out.combatRuntime.clock={round:fresh.sequence.round,actorId:currentEncounterActor(fresh.sequence)||''};
 const rollEvidence=Object.fromEntries(Object.entries(rollsByTarget).map(([id,r])=>[id,cp(r)]));
 for(const id of new Set([stage.casterId,...fresh.targetIds,...Object.keys(proactiveEvades??{})])){
  const journalId=`doom-flame:${stage.id}:${id}`;
  check(!out.journal.some(j=>j.id===journalId),'Duplicitní Area záznam');
  out.journal.push({id:journalId,characterId:id,createdAt:new Date().toISOString(),
   title:`HMK Doom Flame – kolo ${stage.round}`,body:`Doložený Spellfire a Area Fire na ${stage.targetIds.join(', ')}`,
   combatProof:{actionKind:'area-doom-flame',sourceEventId:stage.id,timelineId:stage.timelineId,
    round:stage.round,actorId:stage.casterId,source:cp(fresh.sourceEvent),rollsByTarget:rollEvidence}});
 }
 const serialized=js(out);
 const res=persistVerifiedCombatSnapshot({storage,key,baseline,serialized});
 return {...res,document:res.ok?out:null,serialized:res.ok?serialized:null};
}

/** HMK p202: ordinary failed spellfire must still consume the turn and
 * accrue CL VI casting fatigue. It creates NO Area damage source and
 * requests NO extra impact/shock dice. Critical Failure remains blocked.
 */
export function persistFailedDoomFlame({stage,document,storage,key,baseline}={}){
 check(stage?.format==='hmk-doom-flame-stage-v1'&&stage.phase==='failed'&&stage.castingSL==='F'&&
  js(document)===stage.documentWitness,'Neplatný nebo změněný failed Casting průvodce');
 const seq=validateEncounterSequence(document.combatRuntime.sequence);
 check(js(seq)===stage.sequenceWitness,'Změna Initiative při neúspěšném Spellfire');
 const initial=prepareDoomFlameSource({id:stage.id,sequence:seq,document,casterId:stage.casterId,
  center:stage.center,seedFire:stage.seedFire,conditionsConfirmed:true,gmConfirmed:true});
 const verified=submitDoomFlameDie(initial,stage.castingRoll);
 check(js(verified)===js(stage),'Podvržený casting d100, jeho F výsledek nebo Fatigue');
 const all=Object.fromEntries(document.characters.map(c=>[c.id,c.hmk?.combatState]));
 const newState=cp(all[stage.casterId]);validateCombatState(newState);
 newState.fatigue.windedness+=15;
 newState.events.push({id:stage.id+':failed-casting',round:stage.round,type:'hmk-casting-fatigue',
  details:{spell:'Doom Flame',outcome:'F',fatigue:15,castingRoll:stage.castingRoll}});
 newState.lastRound=Math.max(newState.lastRound,stage.round);validateCombatState(newState);
 check(dueInjuryMorale(newState).length===0,'Kouzelník má splatné Injury Morale');
 const next=cp(seq);next.log.push({type:'area-casting-failed',eventId:stage.id,
  round:stage.round,actorId:stage.casterId,spell:'Doom Flame',castingEML:stage.spellEML,
  castingRoll:stage.castingRoll,physicalDice:[{faces:100,value:stage.castingRoll,source:'GM-entered-physical-die'}]});
 const outcome=finishEncounterTurn(validateEncounterSequence(next),{...all,[stage.casterId]:newState},{action:'incant',gmConfirmed:true});
 check(!outcome.pendingEndTurnAction,'Splatné následky na konci failed Casting');
 const out=cp(document);out.combatRuntime.sequence=outcome;
 out.combatRuntime.clock={round:outcome.round,actorId:currentEncounterActor(outcome)||''};
 out.characters.find(c=>c.id===stage.casterId).hmk.combatState=newState;
 const jid=`doom-flame-failed:${stage.id}`;
 check(!out.journal.some(x=>x.id===jid),'Duplicitní failed Casting důkaz');
 out.journal.push({id:jid,characterId:stage.casterId,createdAt:new Date().toISOString(),
  title:`HMK Doom Flame – neúspěšný Casting, kolo ${stage.round}`,
  body:'HMK p202: F, žádná Area rána; CL VI Casting Fatigue +15.',
  combatProof:{actionKind:'area-doom-flame-failed',sourceEventId:stage.id,round:stage.round,
   castingEML:stage.spellEML,castingRoll:stage.castingRoll,castingSL:'F',castingFatigue:15}});
 const serialized=js(out);const res=persistVerifiedCombatSnapshot({storage,key,baseline,serialized});
 return {...res,document:res.ok?out:null,serialized:res.ok?serialized:null};
}

/** HMK pp.189–190,202–203: Spell Misfire CF, d100 01–99.
 * Form Failures (01–30) add casting fatigue; 31–60 inflict Psyche Stress
 * and Aura warpage; 61–99 inflict Aural Shock and immediate Weakness.
 * Crucial Misfire removes spell mastery. Follow-up mental recovery/trait
 * selection is explicit; d100 100 Total Release remains blocked because
 * Spirit and Raw Principle effects require their own adjudication.
 */
export function persistDoomFlameFormMisfire({stage,document,storage,key,baseline}={}){
 check(stage?.format==='hmk-doom-flame-stage-v1'&&['misfire-form-failure','misfire-mental-trauma'].includes(stage.phase)&&
  stage.castingSL==='CF'&&js(document)===stage.documentWitness,
  'Chybí úplný doložený Spell Misfire z aktuálního dokumentu');
 const seq=validateEncounterSequence(document.combatRuntime.sequence);
 check(js(seq)===stage.sequenceWitness,'Změna Initiative mezi Casting a Misfire');
 const original=prepareDoomFlameSource({id:stage.id,sequence:seq,document,
  casterId:stage.casterId,center:stage.center,seedFire:stage.seedFire,
  conditionsConfirmed:true,gmConfirmed:true});
 const verified=submitDoomFlameDie(submitDoomFlameDie(original,stage.castingRoll),stage.misfireD100);
 check(js(verified)===js(stage),'Podvržené fyzické hody, Misfire nebo Fatigue');
 const all=Object.fromEntries(document.characters.map(c=>[c.id,c.hmk?.combatState]));
 const nextState=cp(all[stage.casterId]);validateCombatState(nextState);
 nextState.fatigue.windedness+=stage.totalCastingFatigue;
 // HMK p189,190,203: Aural Shock immediately adds 5 weakness fatigue
 // per level. Psyche Stress is tracked separately; its trait manifestation
 // remains a subsequent explicit GM/character process, never invented here.
 if(stage.phase==='misfire-mental-trauma')
  applyMisfireCombatTrauma(nextState,classifySpellMisfire(stage.misfireD100,6));
 nextState.events.push({id:stage.id+':spell-misfire',round:stage.round,type:'hmk-spell-misfire',
  details:{spell:'Doom Flame',castingSL:'CF',castingRoll:stage.castingRoll,
   misfireD100:stage.misfireD100,misfireKind:stage.misfireKind,
   castingFatigue:20,extraFatigue:stage.misfireExtraFatigue,
   totalFatigue:stage.totalCastingFatigue,crucial:stage.crucialMisfire,
   psycheStress:stage.misfirePsycheStress??0,auralShock:stage.misfireAuralShock??0}});
 nextState.lastRound=Math.max(nextState.lastRound,stage.round);
 validateCombatState(nextState);
 check(dueInjuryMorale(nextState).length===0,'Zůstala splatná Injury Morale');
 const next=cp(seq);next.log.push({type:stage.phase==='misfire-mental-trauma'?'spell-misfire-mental-trauma':'spell-misfire-form-failure',eventId:stage.id,
  round:stage.round,actorId:stage.casterId,spell:'Doom Flame',misfireKind:stage.misfireKind,
  crucial:stage.crucialMisfire,totalFatigue:stage.totalCastingFatigue,
  physicalDice:[{faces:100,value:stage.castingRoll,source:'GM-entered-physical-die'},
   {faces:100,value:stage.misfireD100,source:'GM-entered-physical-die'}]});
 const result=finishEncounterTurn(validateEncounterSequence(next),{...all,[stage.casterId]:nextState},
  {action:'incant',gmConfirmed:true});
 check(!result.pendingEndTurnAction,'Nevyřešená povinná reakce po Misfire');
 const out=cp(document);out.combatRuntime.sequence=result;
 out.combatRuntime.clock={round:result.round,actorId:currentEncounterActor(result)||''};
 const caster=out.characters.find(c=>c.id===stage.casterId);
 caster.hmk.combatState=nextState;
 if(stage.phase==='misfire-mental-trauma')
  applyMisfireArcaneTrauma(caster.hmk.arcane,classifySpellMisfire(stage.misfireD100,6),stage.id);
 if(stage.crucialMisfire){
  check(caster.hmk.arcane?.knownSpells?.includes('Doom Flame'),'Crucial Misfire: chybí původní známé kouzlo');
  caster.hmk.arcane.knownSpells=caster.hmk.arcane.knownSpells.filter(x=>x!=='Doom Flame');
  caster.hmk.arcane.misfireLostSpells??=[];
  check(!caster.hmk.arcane.misfireLostSpells.includes('Doom Flame'),'Kouzlo již bylo ztraceno');
  caster.hmk.arcane.misfireLostSpells.push('Doom Flame');
 }
 const jid='doom-flame-misfire:'+stage.id;
 check(!out.journal.some(x=>x.id===jid),'Duplicitní Spell Misfire');
 out.journal.push({id:jid,characterId:stage.casterId,createdAt:new Date().toISOString(),
  title:`HMK Doom Flame – ${stage.misfireKind} Misfire`,
  body:`Casting CF, Spell Misfire ${stage.misfireD100}; Fatigue +${stage.totalCastingFatigue}${stage.crucialMisfire?'; Doom Flame nelze sesílat až do nového výzkumu':''}.`,
  combatProof:{actionKind:'area-doom-flame-misfire',sourceEventId:stage.id,
   timelineId:stage.timelineId,round:stage.round,physicalDice:[
    {faces:100,value:stage.castingRoll,source:'GM-entered-physical-die'},
    {faces:100,value:stage.misfireD100,source:'GM-entered-physical-die'}],
   misfireKind:stage.misfireKind,crucial:stage.crucialMisfire,
   psycheStress:stage.misfirePsycheStress??0,auralShock:stage.misfireAuralShock??0,
   castingFatigue:20,extraFatigue:stage.misfireExtraFatigue}});
 const serialized=js(out),res=persistVerifiedCombatSnapshot({storage,key,baseline,serialized});
 return {...res,document:res.ok?out:null,serialized:res.ok?serialized:null};
}
